func SelectSubnetClusterInfoList(ctx context.Context, cluster string, name string,
	status *int, hash string) (map[string]*entity.SubnetClusterInfo, error) {

	hash += "SelectSubnetClusterInfoList"

	if data, err := gcache.Get(ctx, hash); err == nil && data != nil {
		if result, ok := data.Val().(map[string]*entity.SubnetClusterInfo); ok {
			return result, nil
		}
	}

	var (
		list []*entity.SubnetClusterInfo
		err  error
	)

	model := dao.SubnetClusterInfo.Ctx(ctx)

	if cluster != "" {
		model = model.Where(dao.SubnetClusterInfo.Columns().Cluster, cluster)
	}
	if name != "" {
		model = model.WhereLike(dao.SubnetClusterInfo.Columns().Name, "%"+name+"%")
	}
	if status != nil {
		model = model.Where(dao.SubnetClusterInfo.Columns().Status, *status)
	}

	err = model.OrderDesc(dao.SubnetClusterInfo.Columns().UpdateTime).Scan(&list)
	if err != nil {
		return nil, err
	}

	result := make(map[string]*entity.SubnetClusterInfo)
	for _, item := range list {
		if _, exists := result[item.Name]; !exists {
			result[item.Name] = item
		}
	}

	gcache.Set(ctx, hash, result, time.Duration(consts.DefaultCacheDuration))
	return result, nil
}
